import{_ as g,C as i,o as d,c as h,j as e,a as l,E as t,a3 as o}from"./chunks/framework.Q4yG9rk_.js";const q=JSON.parse('{"title":"序卦传","description":"讲六十四卦次序之理的传——从天地万物、夫妇人伦到既济未济，读懂卦与卦之间为什么这样相承。","frontmatter":{"title":"序卦传","description":"讲六十四卦次序之理的传——从天地万物、夫妇人伦到既济未济，读懂卦与卦之间为什么这样相承。","category":"guide","aliases":["序卦传","序卦","xu gua zhuan"],"source":["《周易·序卦传》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/shi-yi/xu-gua-zhuan.md","filePath":"yijing/shi-yi/xu-gua-zhuan.md","lastUpdated":1789714390000}'),y={name:"yijing/shi-yi/xu-gua-zhuan.md"};function x(u,a,p,c,m,b){const s=i("DaoReadingPrelude"),r=i("DaoTextReading"),n=i("DaoKeywordCards");return d(),h("div",null,[a[0]||(a[0]=e("h1",{id:"序卦传",tabindex:"-1"},[l("序卦传 "),e("a",{class:"header-anchor",href:"#序卦传","aria-label":'Permalink to "序卦传"'},"​")],-1)),t(s,{title:"顺着卦与卦之间的理由读",summary:"《序卦传》篇幅不长，却回答了一个重要问题：六十四卦为什么要这样排列？它用「故受之以」把相邻卦连接起来，从天地、万物、资源、冲突与秩序，写到家庭、进退、聚散、动止、诚信，最后落在既济而未济。读它，不是背一串编号，而是看见局面如何生出下一局面。",points:[{label:"先看连接",text:"留意每个「故受之以」：它说明上一种状态为什么会引出下一种状态。"},{label:"再看转折",text:"通会转否，盛会转剥，困会求解；没有一种局面可以永远停留。"},{label:"最后回到人",text:"上经从天地万物展开，下经转入夫妇、家庭、社会与人的进退。"}],hint:"《序卦》提供的是一幅变化地图，不是要求现实必须按六十四步机械运行的剧本。先读它的因果意识，再回到具体卦义。"}),a[1]||(a[1]=o("",12)),t(r,{colophon:"天地生物 · 通塞相因 · 人伦展开 · 既济未济",tone:"ink",sections:[{id:"duan-01",sentences:[["有天地，然后万物生焉。盈天地之间者唯万物，故",{text:"受之以",glossary:"g02"},"《",{text:"屯",glossary:"g03"},"》。"],["屯者，盈也。屯者，物之始生也。物生必",{text:"蒙",glossary:"g04"},"，故",{text:"受之以",glossary:"g02"},"《蒙》。"],["蒙者，蒙也，物之稚也。物稚不可不养也，故",{text:"受之以",glossary:"g02"},"《需》。"],["需者，饮食之道也。饮食必有讼，故",{text:"受之以",glossary:"g02"},"《讼》。讼必有众起，故",{text:"受之以",glossary:"g02"},"《师》。"],["师者，众也。众必有所比，故",{text:"受之以",glossary:"g02"},"《比》。比者，比也。比必有所畜，故",{text:"受之以",glossary:"g02"},"《小畜》。"],["物畜然后有礼，故",{text:"受之以",glossary:"g02"},"《",{text:"履",glossary:"g05"},"》。履而",{text:"泰",glossary:"g06"},"，然后安，故",{text:"受之以",glossary:"g02"},"《泰》。泰者，通也。"],["物不可以终通，故",{text:"受之以",glossary:"g02"},"《",{text:"否",glossary:"g07"},"》。物不可以终否，故",{text:"受之以",glossary:"g02"},"《同人》。与人同者，物必归焉，故",{text:"受之以",glossary:"g02"},"《大有》。"],["有大者，不可以盈，故",{text:"受之以",glossary:"g02"},"《谦》。有大而能谦必豫，故",{text:"受之以",glossary:"g02"},"《豫》。豫必有随，故",{text:"受之以",glossary:"g02"},"《随》。以喜随人者必有事，故",{text:"受之以",glossary:"g02"},"《",{text:"蛊",glossary:"g08"},"》。"]]},{id:"duan-02",sentences:[["蛊者，事也。有事而后可大，故",{text:"受之以",glossary:"g02"},"《临》。临者，大也。物大然后可观，故",{text:"受之以",glossary:"g02"},"《观》。"],["可观而后有所合，故",{text:"受之以",glossary:"g02"},"《噬嗑》。嗑者，合也。物不可以苟合而已，故",{text:"受之以",glossary:"g02"},"《贲》。"],["贲者，饰也。致饰然后亨则尽矣，故",{text:"受之以",glossary:"g02"},"《剥》。剥者，剥也。"],["物不可以终尽剥，穷上反下，故",{text:"受之以",glossary:"g02"},"《复》。复则不妄矣，故",{text:"受之以",glossary:"g02"},"《无妄》。"],["有无妄，物然后可畜，故",{text:"受之以",glossary:"g02"},"《大畜》。物畜然后可养，故",{text:"受之以",glossary:"g02"},"《颐》。颐者，养也。"],["不养则不可动，故",{text:"受之以",glossary:"g02"},"《大过》。物不可以终过，故",{text:"受之以",glossary:"g02"},"《坎》。坎者，陷也。陷必有所丽，故",{text:"受之以",glossary:"g02"},"《离》。离者，丽也。"]]},{id:"duan-03",sentences:[["有天地然后有万物，有万物然后有男女，有男女然后有夫妇，有夫妇然后有父子，有父子然后有君臣，有君臣然后有上下，有上下然后礼义有所错。"],["夫妇之道不可以不久也，故",{text:"受之以",glossary:"g02"},"《恒》。恒者，久也。物不可以久居其所，故",{text:"受之以",glossary:"g02"},"《遁》。遁者，退也。"],["物不可以终遁，故",{text:"受之以",glossary:"g02"},"《大壮》。物不可以终壮，故",{text:"受之以",glossary:"g02"},"《晋》。晋者，进也。进必有所伤，故",{text:"受之以",glossary:"g02"},"《明夷》。"],["夷者，伤也。伤于外者必反于家，故",{text:"受之以",glossary:"g02"},"《家人》。家道穷必乖，故",{text:"受之以",glossary:"g02"},"《睽》。睽者，乖也。"]]},{id:"duan-04",sentences:[["乖必有难，故",{text:"受之以",glossary:"g02"},"《蹇》。蹇者，难也。物不可以终难，故",{text:"受之以",glossary:"g02"},"《解》。解者，缓也。"],["缓必有所失，故",{text:"受之以",glossary:"g02"},"《损》。损而不已必益，故",{text:"受之以",glossary:"g02"},"《益》。益而不已必决，故",{text:"受之以",glossary:"g02"},"《夬》。夬者，决也。"],["决必有遇，故",{text:"受之以",glossary:"g02"},"《姤》。姤者，遇也。物相遇而后聚，故",{text:"受之以",glossary:"g02"},"《萃》。萃者，聚也。"],["聚而上者谓之升，故",{text:"受之以",glossary:"g02"},"《升》。升而不已必困，故",{text:"受之以",glossary:"g02"},"《困》。困乎上者必反下，故",{text:"受之以",glossary:"g02"},"《井》。"],["井道不可不革，故",{text:"受之以",glossary:"g02"},"《革》。革物者莫若鼎，故",{text:"受之以",glossary:"g02"},"《鼎》。主器者莫若长子，故",{text:"受之以",glossary:"g02"},"《震》。震者，动也。"],["物不可以终动，止之，故",{text:"受之以",glossary:"g02"},"《艮》。艮者，止也。物不可以终止，故",{text:"受之以",glossary:"g02"},"《渐》。渐者，进也。"]]},{id:"duan-05",sentences:[["进必有所归，故",{text:"受之以",glossary:"g02"},"《归妹》。得其所归者必大，故",{text:"受之以",glossary:"g02"},"《丰》。丰者，大也。穷大者必失其居，故",{text:"受之以",glossary:"g02"},"《旅》。"],["旅而无所容，故",{text:"受之以",glossary:"g02"},"《巽》。巽者，入也。入而后说之，故",{text:"受之以",glossary:"g02"},"《兑》。兑者，说也。"],["说而后散之，故",{text:"受之以",glossary:"g02"},"《涣》。涣者，离也。物不可以终离，故",{text:"受之以",glossary:"g02"},"《节》。"],["节而信之，故",{text:"受之以",glossary:"g02"},"《中孚》。有其信者必行之，故",{text:"受之以",glossary:"g02"},"《小过》。有过物者必济，故",{text:"受之以",glossary:"g02"},"《",{text:"既济",glossary:"g11"},"》。"],["物不可穷也，故",{text:"受之以",glossary:"g02"},"《",{text:"未济",glossary:"g12"},"》，终焉。"]]}],glossary:[{id:"g01",term:"序卦",pinyin:"xù guà",meaning:"说明六十四卦次序与相承理由的《易传》篇名。它关注卦与卦之间的关系，不是逐卦详解。"},{id:"g02",term:"受之以",pinyin:"shòu zhī yǐ",meaning:"承接、接续于某卦。每一个「故受之以」都在回答：前一状态为什么会带出后一状态。"},{id:"g03",term:"屯",pinyin:"zhūn",meaning:"聚集、艰难，也指万物初生而未舒展的状态。新生之物有生机，也有条件未备的纠结。"},{id:"g04",term:"蒙",pinyin:"méng",meaning:"蒙昧、幼稚。物初生而未明，需要养育、学习与引导；蒙不是终点，而是进入学习的起点。"},{id:"g05",term:"履",pinyin:"lǚ",meaning:"践履、行走，也含有依礼而行、守分知止的意味。物畜之后不能只凭力量，还需要分寸。"},{id:"g06",term:"泰",pinyin:"tài",meaning:"通达、通泰。序卦强调「物不可以终通」，提醒顺境不能被当成永恒状态。"},{id:"g07",term:"否",pinyin:"pǐ",meaning:"闭塞、不通。否并非终局，序卦接着以同人说明闭塞中仍会重新产生共同与连接。"},{id:"g08",term:"蛊",pinyin:"gǔ",meaning:"积弊、败坏之事，也包含整治积弊的任务。随喜而失察，久而久之便可能生蛊。"},{id:"g09",term:"剥复",pinyin:"bō fù",meaning:"剥是剥落，复是返回、复生。剥极不能终尽，穷上反下而复，构成《易》重要的转化节律。"},{id:"g10",term:"咸恒",pinyin:"xián héng",meaning:"咸为感应，恒为长久。下经由夫妇之道开端，写人与人如何感通并在关系中求久。"},{id:"g11",term:"既济",pinyin:"jì jì",meaning:"事情已经渡过、已经完成的状态。它虽成而未必永固，因此下一卦仍是未济。"},{id:"g12",term:"未济",pinyin:"wèi jì",meaning:"尚未渡过、尚未完成。它不是单纯失败，而是保留变化和继续行动的开放结尾。"}],"aria-label":"序卦传原文"}),a[2]||(a[2]=e("blockquote",null,[e("p",null,"注：本页按你提供的通行本文字整理。不同底本在「遁／遁」「无／無」「错／措」「说／悦」等字形、用字和句读上可能有差异，阅读时请以所据版本为准。")],-1)),a[3]||(a[3]=e("h2",{id:"【原典层】字词释义",tabindex:"-1"},[l("【原典层】字词释义 "),e("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),t(n,{items:[{term:"序卦",pinyin:["xù","guà"],meaning:"说明六十四卦次序与相承理由的《易传》篇名。它关注卦与卦之间的关系，不是逐卦详解。"},{term:"受之以",pinyin:["shòu","zhī","yǐ"],meaning:"承接、接续于某卦。每一个「故受之以」都在回答：前一状态为什么会带出后一状态。"},{term:"屯",pinyin:["zhūn"],meaning:"聚集、艰难，也指万物初生而未舒展的状态。新生之物有生机，也有条件未备的纠结。"},{term:"蒙",pinyin:["méng"],meaning:"蒙昧、幼稚。物初生而未明，需要养育、学习与引导；蒙不是终点，而是进入学习的起点。"},{term:"履",pinyin:["lǚ"],meaning:"践履、行走，也含有依礼而行、守分知止的意味。物畜之后不能只凭力量，还需要分寸。"},{term:"泰",pinyin:["tài"],meaning:"通达、通泰。序卦强调「物不可以终通」，提醒顺境不能被当成永恒状态。"},{term:"否",pinyin:["pǐ"],meaning:"闭塞、不通。否并非终局，序卦接着以同人说明闭塞中仍会重新产生共同与连接。"},{term:"蛊",pinyin:["gǔ"],meaning:"积弊、败坏之事，也包含整治积弊的任务。随喜而失察，久而久之便可能生蛊。"},{term:"剥复",pinyin:["bō","fù"],meaning:"剥是剥落，复是返回、复生。剥极不能终尽，穷上反下而复，构成《易》重要的转化节律。"},{term:"咸恒",pinyin:["xián","héng"],meaning:"咸为感应，恒为长久。下经由夫妇之道开端，写人与人如何感通并在关系中求久。"},{term:"既济",pinyin:["jì","jì"],meaning:"事情已经渡过、已经完成的状态。它虽成而未必永固，因此下一卦仍是未济。"},{term:"未济",pinyin:["wèi","jì"],meaning:"尚未渡过、尚未完成。它不是单纯失败，而是保留变化和继续行动的开放结尾。"}]}),a[4]||(a[4]=o("",39))])}const _=g(y,[["render",x]]);export{q as __pageData,_ as default};
